import pandas as pd, numpy as np
d=pd.read_csv('data/redrafted.csv')
def mk(cols, prefix):
    for c in cols:
        d[prefix+c]=(d[c]-d[c].min())/(d[c].max()-d[c].min())*100
    d['r_'+prefix]=d[[prefix+c for c in cols]].mean(axis=1)
mk(['VORP_top','WS_top','WA_top','RWAR_top'],'t')
mk(['VORP','WS','WA','RWAR'],'c')
def nb(name,year,col,played=False,strict=True):
    r=d[(d.name==name)&(d.year==year)]
    p=r.pick.values[0]; val=r[col].values[0]
    pool=d[(d.year==year)&(d.pick>p)]
    if played: pool=pool[pool.seasons.notna()]
    return (pool[col]>val).sum(), (pool[col]>=val).sum()
targets=[('Cedric Simmons',2006,23),('Hilton Armstrong',2006,20),('Julian Wright',2007,15),('Austin Rivers',2012,15),('Buddy Hield',2016,5),('Quincy Pondexter',2010,6),('Andrei Kirilenko',1999,1),('Tony Parker',2001,1),('Quentin Richardson',2000,1),('David West',2003,0)]
for n,y,t in targets:
    print(n,y,'target',t)
    for col in ['r_t','r_c']:
        for played in [False,True]:
            print('  ',col,'played' if played else 'all', nb(n,y,col,played))
